import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); String line = br.readLine(); if (line != null) { int t = Integer.parseInt(line.trim()); while (t-- > 0) { int n = Integer.parseInt(br.readLine().trim()); if (n % 2 != 0) { out.println("Alice"); } else { out.println("Bob"); } } } out.flush(); out.close(); } }